In this paper, we develop and analyze a novel normal-map based second-order approach for the composite optimization problem
%
\begin{align} \label{eq1-1}
\min\limits_{x\in\mathbb{R}^n}~\psi(x):=f(x)+\varphi(x),
\end{align}

where $f:\mathbb{R}^n\rightarrow\mathbb{R}$ is a continuously differentiable (not necessarily convex) function and $\varphi:\mathbb{R}^n\rightarrow(-\infty,\infty]$ is a convex, lower semicontinuous (lsc), and proper (not necessarily smooth) mapping. 


where $\oprox : \Rn \to \Rn$, $\prox{x} := \argmin_{y \in \Rn} \varphi(y) + \frac{1}{2\lambda} \|x-y\|^2$ denotes the well-known proximity operator of $\varphi$, \cite{Mor65}, and $\lambda > 0$ is a positive parameter. Alternatively, the forward-backward scheme in \eqref{eq:fbs-intro} can also be interpreted as a fixed-point procedure applied to the nonsmooth equation:


By $\iprod{\cdot}{\cdot}$ and $\|\cdot\|$ we denote the standard Euclidean inner product and norm. For matrices, the norm $\|\cdot \|$ is the standard spectral norm. The sets of symmetric and symmetric positive definite $n \times n$ matrices are denoted by $\mathbb S^n$ and $\Spp$, respectively. For a given matrix $A \in \Spp$, we define the norm $\|x\|_A := \sqrt{\iprod{x}{Ax}}$. For two matrices $A, B \in \mathbb S^n$, we write $A\succeq B$ if $A-B$ is positive semidefinite. We use $\mathrm{ri}(S)$ to denote the relative interior of a convex set $S \subset \Rn$.


As mentioned, $\oprox$ denotes the proximity operator of $\varphi$ with respect to the scalar $\lambda$. 
The proximity operator is a {firmly nonexpansive mapping}, i.e.,
%
\be \label{eq:prox-nonexp} \|\prox{x}-\prox{y}\|^2\leq\langle x-y,\prox{x}-\prox{y} \rangle \quad \forall~x,y \in \Rn. \ee

In particular, $\oprox$ is globally Lipschitz continuous with constant 1. Moreover, the proximity operator can be characterized by the associated optimality conditions of its underlying optimization problem:
%
\begin{align}\label{eq1-3}
\prox{x}\in x-\lambda \partial\varphi(\prox{x}). 
\end{align}

We will also work with the Moreau envelope $\env{x}:=\min_y\varphi(y)+\frac{1}{2\lambda}\|x-y\|^2$. It is well known that $\oenv$ is convex and continuously differentiable and its gradient is given by $\nabla\env{x}=\frac{1}{\lambda}(x-\prox{x})$. Let us further note that due to the convexity of $\vp$ and differentiability of $f$, Clarke's subdifferential $\partial \psi$ coincides with the regular and limiting subdifferential of $\psi$. We refer to \cite{Mor65,rockafellar2009variational,BauCom11} for additional details and background. 


\begin{align} \label{normal_eq} \Fnor{z} := \nabla f(\prox{z})+{\lambda^{-1}}(z-\prox{z}) =0 \end{align}

\begin{align}\label{eq3-4}
  \min_{q}~m_k(q):=\iprod{\Fnor{z_k}}{D_kq} + \frac{1}{2} \iprod{M_kq}{D_kq} \quad \text{s.t.} \quad \|q\|\leq\Delta_k,
\end{align}

where $\Delta_k$ is the trust region radius. %As mentioned, the Steihaug-CG method can be utilized to solve the subproblem \eqref{eq3-4} inexactly. 
Let $\bar q_k$ denote an approximate solution of the subproblem \eqref{eq3-4} returned by the Steihaug-CG method. Motivated by our previous discussion, we can then generate a lifted and rescaled step $s_k$ via


\be \label{eq:def-sk-bar-sk} \bar s_k = \bar q_k - \lambda  (\Fnor{z_k}+M_k\bar q_k) \quad \text{and} \quad s_k = \min\left\{1,{\Delta_k}/{\|\bar s_k\|}\right\} \bar s_k, \ee

\begin{defn} \label{def:mer}
Let $\lambda > 0$, $\tau \in (0,1)$ be given. We define the merit function
$$ \mer: \Rn \to \R, \quad \mer(z):=\psi(\prox{z})+\frac{\tau\lambda}{2}\|\Fnor{z}\|^2. $$
%where $\tau \in [0,1-\nu)$, $\nu \in [0,1)$. %Furthermore, the criticality measure $\chi$ is set to $\chi(z):=\|\Fnor{z}\|_{\lambda }$.
\end{defn}

Based on \cref{def:mer}, we define the actual reduction term $\mathrm{ared}_k$ via:  
%
\[ \mathrm{ared}_k := \mer(z_k) - \mer(z_k+s_k). \]


Here, $\chi:\mathbb{R}^n\rightarrow\mathbb{R}_{+}$ is a continuous criticality measure. Throughout this work, we will use with the criticality measure %$\chi(z) := \|\Fnor{z}\|$.
%
\[ \chi(z) := \|\Fnor{z}\|. \]


\begin{align}  \label{eq:pred} \mathrm{pred}(z,s,\Delta,\nu) & := \frac{\tau\chi(z)}{2} \min\{\lambda,\Delta,\lambda\chi(z)\} \\ & \hspace{8ex} + \frac{\nu \chi(z)}{\min\{\Delta,\lambda\chi(z)\}} \|\prox{z+s} - \prox{z}\|^2, \nonumber \end{align}

where $\tau \in (0,1)$ and $\nu \in [0,1)$ are given. In the next sections, we show that this choice of $\rho_k$, $\mathrm{ared}_k$, and $\mathrm{pred}_k$ meets all the mentioned requirements. The full details of the method are presented in \cref{algo2}. Notice that we allow the usage of approximate Hessian information $B_k \approx \nabla^2 f(\prox{z_k})$. We call iteration $k$ successful if $z_k + s_k$ is accepted as new iterate, i.e., $z_{k+1}=z_k+s_k$.


\begin{algorithm}[t]
        \caption{A Trust Region Normal Map Semismooth Newton Method}
         \label{algo2}
        \begin{algorithmic}[1]
            \Require Choose an initial point $z_0\in\mathbb{R}^n$, $B_0 \in \mathbb{S}^n$, $\lambda>0$, and $\{\epsilon_k\} \subset \R_{+}$. Set iteration $k=0$.
            \While{$F_{\text{nor}}^{\lambda}(z_k)\neq0$}
            \State Choose $D_k\in\partial\text{prox}_{\varphi}^{\lambda}(z_k)$ and set $M_k=B_kD_k+\frac{1}{\lambda}(I-D_k)$.
            \State Run the Steihaug-CG method with $S = D_k M_k$, $g = D_k \Fnor{z_k}$, $\Delta = \Delta_k$, and $\epsilon = \epsilon_k \geq 0$ returning $\bar q_k = q$;
            \State Set $\bar{s}_k=\bar q_k-\lambda (F_{\text{nor}}^{\lambda}(z_k)+M_k\bar q_k)$ and $s_k=\min\{1,\frac{\Delta_k}{\|\bar{s}_k\|}\}\bar{s}_k$;
            %\EndIf
             \If{$\rho_k=\frac{\mer(z_k)-\mer(z_k+s_k)}{\mathrm{pred}(z_k,s_k,\Delta_k,\nu_k)} < \eta_1$}
             \State Set $z_{k+1}=z_{k}$ and $B_{k+1} = B_k$;
             \Else
             \State Set $z_{k+1}=z_k+s_k$ and choose $B_{k+1} \approx \nabla^2 f(\prox{z_{k+1}})$;
             \EndIf
             \State Set $\Delta_{k+1}$ based on $\rho_k$ by invoking \cref{algo3};
             \State $k\gets k+1$;
            \EndWhile
        \end{algorithmic}
    \end{algorithm}

\begin{algorithm}[t]
        \caption{Update of the Trust Region Radius}
        \label{algo3}
        \begin{algorithmic}[1]  
            \Require Input: $\Delta_k,\rho_k$. Let $\eta_1\leq\eta_2<1$ and $0<\gamma_0<\gamma_1<1<\gamma_2$, and $\Delta_{\min} \geq 0$ be fixed. \vspace{0.1ex}
           \State Select $\Delta_{k+1}\in \begin{cases} (\gamma_0\Delta_k,\gamma_1\Delta_k] & \text{if }  \rho_k < \eta_1, \\ [\gamma_1\Delta_k,\max\{\Delta_{\min},\Delta_k\}]\cap[\Delta_{\min},\infty) & \text{if } \rho_k\in[\eta_1,\eta_2)\\ (\Delta_k,\max\{\Delta_{\min},\gamma_2\Delta_k\}]\cap[\Delta_{\min},\infty) & \text{if } \rho_k \geq \eta_2 \end{cases}$;
%           \If{$\rho_k < \eta_1$}
%           \State Set $\Delta_{k+1}\in (\gamma_0\Delta_k,\gamma_1\Delta_k]$.
%           \ElsIf{$\rho_k\in[\eta_1,\eta_2)$}
%           \State Set $\Delta_{k+1}\in[\gamma_1\Delta_k,\max\{\Delta_{\min},\Delta_k\}]\cap[\Delta_{\min},\infty)$;
%           \Else
%          \State Set $\Delta_{k+1}\in(\Delta_k,\max\{\Delta_{\min},\gamma_2\Delta_k\}]\cap[\Delta_{\min},\infty)$;
%           \EndIf
           \State Return $\Delta_{k+1}$;
        \end{algorithmic}
\end{algorithm}

\begin{algorithm}[th]
        \caption{The Steihaug-CG Method}
          \label{algo1}
        \begin{algorithmic}[1]  
            \Require Input: $S \in \R^{n\times n}$, $g \in \Rn$, $\epsilon, \Delta \geq 0$. Set $q_0=0$, $r_0=g$, $p_0 = -g$ and $i=0$.
            \If{$\|r_0\|<\epsilon$}
            \State return $q = q_0$;
            \EndIf
            \While{$i\leq n-1$}
                    \If{$\iprod{p_i}{Sp_i}\leq0$}
                        \State Compute $\alpha_{i}$ such that $\alpha_i=\argmin\limits_{\|q_i+\alpha_ip_i\|=\Delta}m(q_i+\alpha_ip_i)$ and return $q = q_i+\alpha_ip_i$;
                        \Else
                        \State Set $\alpha_i=\frac{\langle r_i,r_i \rangle}{\langle p_i,Sp_i\rangle}$ and $q_{i+1}=q_i+\alpha_ip_i$;
                        \If{$\|q_{i+1}\|\geq\Delta$}
                        \State Reset $\alpha_i$ such that $\alpha_i\geq0$ and $\|q_i+\alpha_ip_i\|=\Delta$ and return $q = q_i+\alpha_ip_i$;
                        \EndIf
                        \State Set $r_{i+1}=r_i+\alpha_iSp_i$;
                        \If{$\|r_{i+1}\|<\epsilon$}
                        \State Return $q = q_{i+1}$;
                        \EndIf
                        \State Set $\beta_{i+1}=\frac{\|r_{i+1}\|^2}{\|r_i\|^2}$ and $p_{i+1}=-r_{i+1}+\beta_{i+1}p_i$;
                    \EndIf
                    \State $i\gets i+1$
            \EndWhile
        \end{algorithmic}
      \end{algorithm}

\begin{assumption}\label{assum2-1} We consider the conditions:
\begin{enumerate}[label=\textup{\textrm{(A.\arabic*)}},topsep=0pt,itemsep=0ex,partopsep=0ex,leftmargin=8ex]
  \item \label{A1} The gradient $\nabla f$ is Lipschitz continuous on $\dom{\vp}$ with modulus $L$.
  \item \label{A2} The objective function $\psi$ is lower bounded on $\dom{\partial\varphi}$.
\end{enumerate}
\end{assumption}

\begin{assumption}
\label{assum2-2}  We assume: 
\begin{enumerate}[label=\textup{\textrm{(B.\arabic*)}},topsep=0pt,itemsep=0ex,partopsep=0ex,leftmargin=8ex]
\item \label{B1} 
The parameters $\tau$ and $\nu_k$ satisfy the conditions: 
%
\[ \nu \in [0,1),\quad 0\leq\nu_k\leq\nu, \quad \text{and} \quad (L^2\lambda^2+2)\tau< 2(1-\nu). \]
%
\item \label{B2} It holds that $\sum_{k=0}^\infty ({1 + \|B_k\|})^{-1} = \infty$. 
\item \label{B3} There is $\kappa_B > 0$ such that $\|B_k\| \leq \kappa_B$ for all $k \in \N$.
\end{enumerate}
\end{assumption}

Condition \ref{B2} holds, e.g., if the matrices $\{B_k\}$ satisfy $\|B_k\| \leq c_{B_1} + c_{B_2} k$ for all $k$ and some $c_{B_1}, c_{B_2} > 0$. Hence, \ref{B2} is generally weaker than \ref{B3}. Let $\{j_i\}$ be an increasing sequence enumerating the indices of the accepted iterates in step 8 of \cref{algo2}. We then define the set of all successful iterations as $\mathcal S := \{j_i : i \geq 0\} = \{k \in \N : \rho_k \geq \eta_1\}$. We will also use the notations 


\be \label{eq:muk-xk} {\mu}_k := \nu_k \chi(z_k) \min\{\Delta_k,\lambda\chi(z_k)\}^{-1} \quad \text{and} \quad x_k := \prox{z_k}, \ee

where $\{z_k\}$ and $\{\Delta_k\}$ denote the sequences generated by \cref{algo2}. %Furthermore,

