\begin{thm}
\label{thm:global_conv}
Let the conditions \ref{A1}--\ref{A2}, \ref{B1}--\ref{B2}, and $\Delta_{\min} > 0$ hold and assume that \cref{algo2} does not terminate after finitely many steps. Then, we have
%
\be \label{eq:liminf-conv} \lim_{k\rightarrow\infty}\chi(z_k)=0 \quad \text{and} \quad \sum_{k=0}^\infty {\mu}_k \|x_{k+1}-x_k\|^2 < \infty. \ee
%
\end{thm}

