\begin{lemma} \label{prop2-5} 
Let $D\in\partial\prox{x} \subseteq \R^{n \times n}$, $x \in \Rn$, be an arbitrary generalized derivative. Then, it holds that: 
\begin{itemize}
\item[\rmn{(i)}] Both $D$ and $I-D$ are symmetric and positive semidefinite matrices.
\item[\rmn{(ii)}] The matrix $D(I-D)$ is positive semidefinite.
\end{itemize}
\end{lemma}

\begin{lemma}
\label{lemma2-1} Let $B, D \in \mathbb{S}^n$ be symmetric matrices and let $r \in \Rn$ and $\epsilon \geq 0$ be given. %Suppose that $D$ is symmetric %and $\Lambda(I-D)$ are symmetric and positive semidefinite 
Let us set $M := B D + \frac{1}{\lambda}(I-D)$ and assume that $y$ satisfies the condition $\|D(My + r)\| \leq \epsilon$. Then, setting $x = y - \lambda (My + r)$, it follows $\|Mx + r\| \leq \|I-\lambda B\| \epsilon$. 
\end{lemma}

\begin{proof}
Applying the definition of $M$, we directly obtain
\begin{align}\label{eq3-3}
\lambda M =\lambda BD +I-D=(\lambda B -I)D+I
\end{align}
%
and
%
%\begin{align*}
$ \|Mx+r\|=\|My-\lambda M (My+r)+r\| =\|(I-\lambda B)D(My+r)\| \leq  \|I - \lambda B \| \epsilon$. 
%\end{align*}
\end{proof}

\begin{lemma}
\label{lemma2-5}
Suppose that \ref{A1} is satisfied and let $z, e \in \Rn$, $\alpha \in (0,1]$, {$\nu \in [0,1)$, and $\tau \in (0,1-\nu)$} be given. Setting $d:=-\Fnor{z}$ and $x := \prox{z}$, it follows
%
\begin{align*}
\mer(z+\alpha\lambda (d+e))-\mer(z) & \leq -\frac{\tau\lambda\alpha}{2}\|\Fnor{z}\|^2 - \frac{\nu}{\lambda\alpha}\|p_\alpha - x\|^2 + \frac{\tau\lambda\alpha}{2} \|e\|^2 \\ & \hspace{4ex} + \left[L\tau\lambda + 1 - \tau\right] \alpha \|e\|\|d+e\| + C(\alpha) \|p_\alpha-x\|^2,
%\mer(z+\alpha\lambda (d+e))-\mer(z) & \\ & \hspace{-25ex} \leq -\frac{\tau\lambda\alpha}{2}\|\Fnor{z}\|^2 - \frac{\nu}{\lambda\alpha}\|p_\alpha - x\|^2 + \left[L\tau + \lambda(1 - \tau)\right] \alpha \|e\|\|d+e\| \\ & \hspace{-19ex} + \frac{\tau\lambda\alpha}{2} \|e\|^2 + C(\alpha) \|p_\alpha-x\|^2,
\end{align*}
where $p_\alpha := \prox{z+\alpha\lambda (d+e)}$ and $C(\alpha) := (\frac{L^2\lambda^2+2}{2\lambda} \cdot \tau - \frac{1-\nu}{\lambda})\frac{1}{\alpha} + L \tau + \frac{L}{2}-\frac{\tau}{2\lambda}$.
\end{lemma}

\begin{proof} Applying the Lipschitz continuity of $\nabla f$ on $\dom{\vp}$ and $\nabla \env{z+\alpha \lambda (d+e)} = \frac{1}{\lambda}(z+\alpha \lambda  (d+e) - p_\alpha) \in \partial \vp(p_\alpha)$, see \eqref{eq1-3}, we have
%
\begin{align} \label{eq:here-esti1} %\psi(p_\alpha) - \psi(x) & \\ & \hspace{-8ex} 
\psi(p_\alpha) - \psi(x) & \leq  \iprod{\nabla f(x)}{p_\alpha - x}  + \frac{L}{2} \|p_\alpha - x\|^2 + \frac{1}{\lambda}\iprod{z+\alpha \lambda  (d+e) - p_\alpha}{p_\alpha - x} \nonumber \\ & = \iprod{\Fnor{z}+\alpha (d+e)}{p_\alpha - x} + \left[\frac{L}{2}-\frac{1}{\lambda}\right] \|p_\alpha - x\|^2 \nonumber \\ & = (1-\alpha) \iprod{\Fnor{z} - e}{p_\alpha - x} + \iprod{e}{p_\alpha - x} + \left[\frac{L}{2}-\frac{1}{\lambda}\right] \|p_\alpha - x\|^2. \end{align}
%
Moreover, it holds that
%
