                        \Else
                        \State Set $\alpha_i=\frac{\langle r_i,r_i \rangle}{\langle p_i,Sp_i\rangle}$ and $q_{i+1}=q_i+\alpha_ip_i$;
                        \If{$\|q_{i+1}\|\geq\Delta$}
